        'employment_return' => ['code' => 'ss', 'title' => 'Employment Information Return working', 'category' => 'annual', 'frequency' => 'yearly', 'basis' => 'financial', 'scope' => 'establishment', 'builder' => 'employment_return', 'min_employees' => 20, 'threshold_measure' => 'employed_period_end', 'threshold_basis' => 'SS (Central) Rules, 2026 r.56, Explanation (B): private establishment = 20 or more employees', 'threshold_confidence' => 'OFFICIAL_SOURCE_PARTIALLY_VERIFIED', 'output' => 'working_sheet', 'filing' => 'Career Centre / National Career Service portal, as the state specifies', 'effective_from' => '2026-05-08', 'form' => 'Form XXVI (replaces ER-I and ER-II)', 'legal_basis' => 'Code on Social Security, 2020 Chapter XIII; SS (Central) Rules, 2026 r.56(6)', 'due' => ['months_after' => 1, 'day' => 30], 'due_text' => 'within 30 days after 31 March (by 30 April)', 'confidence' => 'OFFICIAL_PRIMARY_SOURCE_VERIFIED', 'sources' => [['Social Security (Central) Rules, 2026 — G.S.R. 344(E), 8 May 2026, Gazette CG-DL-E-08052026-272366 (MoLE copy)', 'https://www.labour.gov.in/static/uploads/2026/05/49aa9b62c2125499c37399b90e969d67.pdf']], 'verified_on' => '2026-10-26', 'legal_review' => 'For private establishments the duty starts from the date the appropriate government notifies (r.56(1)(b)); the yearly return is filed as the state specifies.'],
        'employment_return_er1' => ['title' => 'Quarterly employment return (ER-I) working', 'category' => 'return', 'frequency' => 'quarterly', 'basis' => 'calendar', 'scope' => 'establishment', 'builder' => 'employment_return', 'min_employees' => 25, 'threshold_measure' => 'employed_period_end', 'threshold_basis' => 'Employment Exchanges (CNV) Act, 1959 s.1(3): private establishments with 25 or more employees', 'threshold_confidence' => 'SECONDARY_SOURCE_ONLY', 'output' => 'working_sheet', 'filing' => 'National Career Service portal', 'effective_to' => '2026-05-07', 'form' => 'Form ER-I', 'legal_basis' => 'Employment Exchanges (Compulsory Notification of Vacancies) Act, 1959 s.5 and Rules, 1960 r.6', 'due' => ['months_after' => 1, 'day' => 30], 'due_text' => 'within 30 days of the quarter end', 'confidence' => 'LEGAL_REVIEW_REQUIRED', 'sources' => [['Social Security (Central) Rules, 2026 — G.S.R. 344(E), 8 May 2026, Gazette CG-DL-E-08052026-272366 (MoLE copy)', 'https://www.labour.gov.in/static/uploads/2026/05/49aa9b62c2125499c37399b90e969d67.pdf'], ['PIB, 21 Nov 2025 — Labour Codes in force; earlier Acts and rules continue during transition', 'https://www.pib.gov.in/PressReleasePage.aspx?PRID=2192463']], 'verified_on' => '2026-10-26', 'legal_review' => 'The CNV Rules, 1960 were superseded by the SS (Central) Rules on 8 May 2026; whether ER-I was still due for quarters after the Code\'s commencement (21 Nov 2025) depends on the transition — confirm.'],
        'bonus_register' => ['title' => 'Bonus register', 'category' => 'annual', 'frequency' => 'yearly', 'basis' => 'financial', 'scope' => 'establishment', 'builder' => 'bonus_register', 'min_employees' => 20, 'threshold_measure' => 'employed_any_day', 'threshold_basis' => 'Code on Wages, 2019 s.41(2): establishments where 20 or more persons are employed on any day of the accounting year', 'threshold_confidence' => 'OFFICIAL_SOURCE_PARTIALLY_VERIFIED', 'options' => ['payment_within_months' => 8], 'output' => 'register', 'filing' => 'Unified annual return, Part I section H (number covered, bonus paid, date)', 'form' => 'No form prescribed under the Code (internal register on the lines of the earlier Form C)', 'legal_basis' => 'Code on Wages, 2019 Chapter IV s.26–41; Wages (Central) Rules, 2026', 'due' => ['months_after' => 8, 'day' => 'end'], 'due_text' => 'credited within 8 months of the close of the accounting year (30 November)', 'confidence' => 'OFFICIAL_SOURCE_PARTIALLY_VERIFIED', 'sources' => [['Code on Wages (Central) Rules, 2026 — G.S.R. 343(E), 8 May 2026, Gazette CG-DL-E-08052026-272365 (MoLE copy)', 'https://www.labour.gov.in/static/uploads/2026/05/6eb0c35ba63b776487a025e5123b6b12.pdf']], 'verified_on' => '2026-10-27', 'legal_review' => 'Bonus ceilings come from the BONUS rule version (prepared for review, not in force); whether central notifications bind state-sphere establishments needs review.'],
        'gratuity_register' => ['code' => 'ss', 'title' => 'Gratuity eligibility and liability', 'category' => 'annual', 'frequency' => 'yearly', 'basis' => 'financial', 'scope' => 'establishment', 'builder' => 'gratuity_register', 'min_employees' => 10, 'threshold_measure' => 'gratuity_coverage', 'threshold_basis' => 'Code on Social Security, 2020 First Schedule, Chapter V: every factory, mine, oilfield, plantation, port and railway company, and every shop or establishment in which ten or more employees are or were employed on any day of the preceding twelve months; s.1(8): coverage continues when the number later falls (India Code text, as on 21 Nov 2025; checked 2026-10-27)', 'threshold_confidence' => 'OFFICIAL_PRIMARY_SOURCE_VERIFIED', 'output' => 'register', 'obligation' => 'statutory', 'form' => 'No register prescribed; nominations in Form III, applications Form IV, employer notice Form V', 'legal_basis' => 'Code on Social Security, 2020 Chapter V s.53–58; SS (Central) Rules, 2026 r.32–33', 'due_text' => 'Paid by the 30th day after the application', 'confidence' => 'OFFICIAL_SOURCE_PARTIALLY_VERIFIED', 'sources' => [['Social Security (Central) Rules, 2026 — G.S.R. 344(E), 8 May 2026, Gazette CG-DL-E-08052026-272366 (MoLE copy)', 'https://www.labour.gov.in/static/uploads/2026/05/49aa9b62c2125499c37399b90e969d67.pdf'], ['Code on Social Security, 2020 (India Code, as on 21 Nov 2025): s.1(8), First Schedule', 'https://www.indiacode.nic.in/bitstream/123456789/16823/1/aA2020-36.pdf']], 'verified_on' => '2026-10-27', 'notes' => ['A liability and eligibility working register; the statute prescribes no register.', 'Coverage is decided as the First Schedule decides it (GratuityEntitlements::coverage): factories, mines and plantations whatever their size; others from ten employees on their busiest day, and once covered, always. Contract labour and others PeopleOS does not hold are not counted.']],
        'equal_remuneration' => ['title' => 'Equal remuneration check', 'category' => 'annual', 'frequency' => 'yearly', 'basis' => 'financial', 'scope' => 'establishment', 'builder' => 'equal_remuneration', 'output' => 'check', 'obligation' => 'internal_control', 'form' => 'No form prescribed under the Code (earlier Form D of the Equal Remuneration Rules, 1976)', 'legal_basis' => 'Code on Wages, 2019 s.3 (no discrimination on the ground of gender)', 'due_text' => 'Review yearly', 'confidence' => 'OFFICIAL_SOURCE_PARTIALLY_VERIFIED', 'sources' => [['Code on Wages (Central) Rules, 2026 — G.S.R. 343(E), 8 May 2026, Gazette CG-DL-E-08052026-272365 (MoLE copy)', 'https://www.labour.gov.in/static/uploads/2026/05/6eb0c35ba63b776487a025e5123b6b12.pdf']], 'verified_on' => '2026-10-27'],
        'holiday_list' => ['title' => 'List of national, festival and paid holidays', 'category' => 'annual', 'frequency' => 'yearly', 'basis' => 'calendar', 'scope' => 'establishment', 'builder' => 'holiday_list', 'source' => 'attendance', 'output' => 'register', 'form' => 'Notice of holidays (state national and festival holidays Acts)', 'legal_basis' => 'State industrial establishments (national and festival holidays) Acts; shops and establishments Acts', 'due_text' => 'Displayed before the year begins', 'confidence' => 'UNVERIFIED', 'sources' => [['OSH and Working Conditions (Central) Rules, 2026 — G.S.R. 345(E), 8 May 2026, Gazette CG-DL-E-09052026-272379 (MoLE copy with a valid Government of India Press signature)', 'https://www.labour.gov.in/static/uploads/2026/05/ee246f790cad0b8e99c3828f34fa09a6.pdf']], 'verified_on' => '2026-10-27', 'legal_review' => 'State notice form and timing not verified. No central form exists: the OSH (Central) Rules, 2026 prescribe only weekly and compensatory holiday notices (r.67–68). State national and festival holidays Acts (e.g. Karnataka 1963, Tamil Nadu 1958, Kerala 1958, Andhra Pradesh 1974) were identified but not read, nor whether they survive the OSH Code.'],
