                'pt_statement' => ['title' => 'Professional tax statement', 'category' => 'return', 'frequency' => 'half_yearly', 'basis' => 'financial', 'scope' => 'state', 'builder' => 'pt_statement', 'output' => 'statement', 'filing' => 'State professional tax portal (payment and return)', 'form' => 'Form 14 (with remittance); Form 15 (employee-wise return)', 'legal_basis' => 'Tamil Nadu Urban Local Bodies Act, 1998 ss.117-B, 117-C; TN Urban Local Bodies Rules, 2023 rr.277–278 (professional tax by the local body)', 'due' => ['months_after' => 0, 'day' => 'end'], 'due_text' => 'deducted from the August and January pay bills; paid with Form 14 by 30 September and 31 March (r.277(2)–(3))', 'confidence' => 'OFFICIAL_SOURCE_PARTIALLY_VERIFIED', 'sources' => [['Tamil Nadu Urban Local Bodies Rules, 2023 — G.O. Ms. No. 45, MAWS, 12-04-2023, rr.274–282 (gazette print on a tn.gov.in host)', 'https://tnurbantree.tn.gov.in/sivagangai/wp-content/uploads/sites/38/2023/07/2023-Service-Rules-404-pages.pdf'], ['Greater Chennai Corporation — Revenue (professional tax)', 'https://chennaicorporation.gov.in/gcc/department/revenue/'], ['Greater Chennai Corporation press release of 04-08-2026', 'https://chennaicorporation.gov.in/gcc/pdf/PT_Press_Release.pdf']], 'verified_on' => '2026-10-27', 'notes' => ['Greater Chennai Corporation from 1 Oct 2024, per half-year: nil to ₹21,000; ₹180; ₹425; ₹930; ₹1,025; ₹1,250 above ₹75,000.', 'Band chosen on the average half-yearly income of the previous financial year (r.274(a)); bonus and gratuity are excluded from salary (r.274(e)). Where a council has made no general revision, the r.275(2) default table applies: nil to ₹21,000; ₹135; ₹315; ₹690; ₹1,025; ₹1,250.'], 'legal_review' => 'Greater Chennai Corporation\'s 2024 rates come from its rate page, not the council resolution; other local bodies\' revisions and panchayat levies are not confirmed. The rule pack\'s Tamil Nadu version deducts monthly on the r.275(2) table: wrong structure for every local body and wrong amounts in Chennai since October 2024.'],
                'lwf_statement' => ['title' => 'Labour welfare fund statement', 'category' => 'challan', 'frequency' => 'yearly', 'basis' => 'calendar', 'scope' => 'state', 'builder' => 'lwf_statement', 'output' => 'statement', 'filing' => 'State labour welfare board', 'form' => 'Form A (r.12(4))', 'legal_basis' => 'Tamil Nadu Labour Welfare Fund Act, 1972 s.15 (amended 2021); TN LWF Rules, 1973 r.11-A, r.12; G.O.(Ms) 161 of 2 Dec 2022', 'due' => ['months_after' => 1, 'day' => 'end'], 'due_text' => 'year ending December, paid by 31 January (Form A); the board\'s copy of r.12 says June wages, paid before 31 July — sources conflict', 'confidence' => 'CONFLICTING_SOURCES', 'sources' => [['TN Government Gazette Extra. No. 538, 02-12-2022 (SRO A-26(b)/2022: ₹20 / ₹40)', 'https://www.lwb.tn.gov.in/uploads/labo_205/subpage_files/Gazette_538.pdf'], ['TN Government Gazette Extra. No. 21, 23-01-2015 (SRO A-1(a)/2015: ₹10 / ₹20)', 'https://www.stationeryprinting.tn.gov.in/extraordinary/2015/21-Ex-III-1a.pdf'], ['Tamil Nadu Labour Welfare Board — G.O.(Ms) 161', 'https://www.lwb.tn.gov.in/uploads/labo_205/subpage_files/GO_161.pdf'], ['Tamil Nadu Labour Welfare Fund Rules, 1973', 'https://www.lwb.tn.gov.in/uploads/labo_205/subpage_files/Tamil_Nadu_Labour_Welfare_Fund_Rules_1973.PDF'], ['Form A', 'https://www.lwb.tn.gov.in/uploads/labo_205/subpage_files/FORM%20A.pdf']], 'verified_on' => '2026-10-27', 'notes' => ['₹20 / ₹40 from 2 Dec 2022; ₹10 / ₹20 from 23 Jan 2015; ₹7 / ₹14 before (official gazettes).', 'PeopleOS does not hold the state\'s managerial and supervisory exclusions (wage ceilings differ by state): check who is excluded before relying on the statement.'], 'legal_review' => 'Deduction month and due date conflict: r.12 (June wages, paid before 31 July) against the official Form A and the board\'s practice (year ending December, paid by 31 January). The rule pack\'s Tamil Nadu version is dated from 2015 with the 2022 amounts.'],
